<?php
require_once __DIR__ . '/../database/config.php';
require_once __DIR__.'/../database/config.php';require_once __DIR__.'/../process/accessControlHelpers.php';require_once __DIR__.'/../common/displayHelpers.php';
$pdo=getDB();requirePageAccess($pdo,'billing_list');if(!function_exists('e')){function e($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}}
$q=trim((string)($_GET['q']??$_GET['search']??''));$type=(string)($_GET['type']??'all');$status=(string)($_GET['status']??'all');$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$rows=[];$error='';
try{
 $sql="SELECT * FROM (
 SELECT 'water' bill_type,br.reading_id source_id,br.global_ref_number,br.member_id,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')) member_name,m.account_number,br.billing_date bill_date,br.due_date,br.amount_due total_amount,CASE WHEN br.is_paid=1 THEN br.amount_due ELSE 0 END amount_paid,CASE WHEN br.is_paid=1 THEN 0 ELSE br.amount_due END balance,CASE WHEN br.is_paid=1 THEN 'paid' WHEN br.due_date<CURDATE() AND br.is_billed=1 THEN 'overdue' WHEN br.is_billed=1 THEN 'unpaid' ELSE 'draft' END bill_status FROM bill_readings br JOIN water_accounts m ON m.pkey=br.member_id WHERE COALESCE(br.bill_lifecycle_status,'active')='active'
 UNION ALL SELECT 'onetime',b.bill_id,b.global_ref_number,b.member_id,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')),m.account_number,b.bill_date,b.due_date,b.total_amount,b.amount_paid,GREATEST(0,b.total_amount-b.amount_paid),CASE WHEN b.status='unpaid' AND b.due_date<CURDATE() THEN 'overdue' ELSE b.status END FROM one_time_bills b JOIN water_accounts m ON m.pkey=b.member_id WHERE COALESCE(b.bill_lifecycle_status,'active')='active'
 UNION ALL SELECT 'installment',ib.installment_id,ib.global_ref_number,ib.member_id,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')),m.account_number,ib.start_date,MAX(s.due_date),ib.total_amount,COALESCE(SUM(CASE WHEN s.status='paid' THEN s.amount ELSE 0 END),0),GREATEST(0,ib.total_amount-COALESCE(SUM(CASE WHEN s.status='paid' THEN s.amount ELSE 0 END),0)),CASE WHEN ib.status='completed' THEN 'paid' WHEN ib.status IN ('cancelled','deleted') THEN ib.status WHEN MAX(CASE WHEN s.status='pending' AND s.due_date<CURDATE() THEN 1 ELSE 0 END)=1 THEN 'overdue' ELSE 'unpaid' END FROM installment_bills ib JOIN water_accounts m ON m.pkey=ib.member_id LEFT JOIN installment_schedules s ON s.installment_id=ib.installment_id WHERE COALESCE(ib.bill_lifecycle_status,'active')='active' GROUP BY ib.installment_id
 UNION ALL SELECT 'recurring',rb.bill_id,rb.global_ref_number,rb.member_id,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')),m.account_number,rb.bill_date,rb.due_date,rb.total_amount,rb.amount_paid,GREATEST(0,rb.balance),CASE WHEN rb.status='unpaid' AND rb.due_date<CURDATE() THEN 'overdue' ELSE rb.status END FROM recurring_bills rb JOIN water_accounts m ON m.pkey=rb.member_id WHERE COALESCE(rb.bill_lifecycle_status,'active')='active'
 ) x WHERE (?='all' OR bill_type=?) AND (?='all' OR bill_status=?) AND (?='' OR member_name LIKE ? OR account_number LIKE ? OR CAST(global_ref_number AS CHAR) LIKE ? OR CAST(source_id AS CHAR) LIKE ?) AND (?='' OR bill_date>=?) AND (?='' OR bill_date<=?) ORDER BY COALESCE(bill_date,'1900-01-01') DESC,source_id DESC LIMIT 3000";
 $s=$pdo->prepare($sql);$like="%$q%";$s->execute([$type,$type,$status,$status,$q,$like,$like,$like,$like,$from,$from,$to,$to]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){$error='Unable to load billing register: '.$e->getMessage();}
$total=array_sum(array_column($rows,'total_amount'));$paid=array_sum(array_column($rows,'amount_paid'));$balance=array_sum(array_column($rows,'balance'));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billing List - <?= htmlspecialchars(app_name(), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="../common/fonts.css"><style>*{box-sizing:border-box}body{margin:0;background:#f8f9fb;color:#111827;font-family:Sora,sans-serif}.page{max-width:1500px;margin:auto;padding:30px}h1{margin:0;font-size:1.5rem}.sub{color:#6b7280;font-size:.84rem;margin:5px 0 20px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:15px}.metric{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:14px}.metric small{color:#6b7280;font-weight:700}.metric strong{display:block;font:700 1.1rem 'JetBrains Mono';margin-top:5px}.filters{display:flex;gap:8px;flex-wrap:wrap;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px;margin-bottom:14px}.filters input,.filters select{height:38px;border:1px solid #d1d5db;border-radius:8px;padding:0 9px;font:inherit}.filters input[name=q]{flex:1;min-width:220px}.btn{height:38px;border:0;border-radius:8px;background:#111827;color:#fff;padding:0 14px;font-weight:700}.table{overflow:auto;background:#fff;border:1px solid #e5e7eb;border-radius:13px}table{width:100%;border-collapse:collapse;min-width:960px}th,td{padding:10px 12px;border-bottom:1px solid #eef0f2;text-align:left;font-size:.76rem}th{background:#f8fafc;text-transform:uppercase;font-size:.64rem;color:#6b7280;position:sticky;top:0}.mono,.money{font-family:'JetBrains Mono'}.money{text-align:right}.badge{font-size:.63rem;font-weight:800;padding:5px 8px;border-radius:999px;background:#f3f4f6}.paid{background:#ecfdf5;color:#047857}.overdue{background:#fef2f2;color:#b91c1c}.unpaid{background:#fffbeb;color:#b45309}.alert{background:#fef2f2;color:#b91c1c;padding:12px;border-radius:10px;margin-bottom:14px}@media(max-width:700px){.page{padding:20px 14px}.metrics{grid-template-columns:1fr}}</style></head><body><?php require_once '../common/navbar.php';?><div class="main-content"><main class="page"><h1>Unified Billing List</h1><div class="sub">Read-only register of water, one-time, installment, and recurring receivables. Corrections use the controlled Billing Adjustments workflow.</div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="metrics" id="blMetrics" data-live-results><div class="metric"><small>Total billed</small><strong>₱<?=number_format($total,2)?></strong></div><div class="metric"><small>Recorded paid</small><strong>₱<?=number_format($paid,2)?></strong></div><div class="metric"><small>Outstanding</small><strong>₱<?=number_format($balance,2)?></strong></div></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Member, account, reference" data-live-search><select name="type"><option value="all">All bill types</option><?php foreach(['water'=>'Water','onetime'=>'One-Time','installment'=>'Installment','recurring'=>'Recurring'] as $v=>$l):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><select name="status"><option value="all">All statuses</option><?php foreach(['draft','unpaid','overdue','paid','cancelled','deleted'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Apply</button></form><div class="table" id="blRecords" data-live-results><table><thead><tr><th>Type</th><th>Reference</th><th>Account</th><th>Member</th><th>Bill Date</th><th>Due Date</th><th class="money">Total</th><th class="money">Paid</th><th class="money">Balance</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(ucfirst($r['bill_type']))?></td><td class="mono" title="<?=e($r['global_ref_number']?:$r['source_id'])?>"><?=e(ui_compact_reference($r['global_ref_number']?:$r['source_id'],19))?></td><td class="mono"><?=e($r['account_number'])?></td><td><?=e($r['member_name'])?></td><td><?=e($r['bill_date'])?></td><td><?=e($r['due_date'])?></td><td class="money">₱<?=number_format((float)$r['total_amount'],2)?></td><td class="money">₱<?=number_format((float)$r['amount_paid'],2)?></td><td class="money">₱<?=number_format((float)$r['balance'],2)?></td><td><span class="badge <?=e($r['bill_status'])?>"><?=e(strtoupper($r['bill_status']))?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="10" style="text-align:center;padding:35px;color:#6b7280">No billing records matched.</td></tr><?php endif;?></tbody></table></div></main></div></body></html>
